create table public.conversations (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, document_id uuid references public.documents(id) on delete set null, title text not null default 'Nouvelle conversation', created_at timestamptz not null default now());
create table public.conversation_messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id) on delete cascade, role text not null check (role in ('user','assistant','system')), content text not null, action text, created_at timestamptz not null default now());
create table public.generation_jobs (id uuid primary key default gen_random_uuid(), document_id uuid references public.documents(id) on delete cascade, requested_by uuid not null references public.profiles(id) on delete cascade, organization_id uuid not null references public.organizations(id) on delete cascade, model text not null, prompt_version text not null, status public.job_status not null default 'queued', tokens_in integer default 0, tokens_out integer default 0, estimated_cost numeric(12,6) default 0, duration_ms integer, error_message text, created_at timestamptz not null default now());
create index generation_jobs_organization_idx on public.generation_jobs(organization_id);
